#!/usr/bin/env bash
# Единый перенос живого стенда ITles (шлюз + симулятор парка) с песочницы Zo на VPS.
# Запускать НА VPS от обычного пользователя (agentuser):
#
#   STAND_KEY='itg_...' bash stand-migrate-vps.sh
#
# STAND_KEY — ключ шлюза вида itg_… (Настройки → Ключи шлюзов; хэш уже зарегистрирован в БД).
# Скрипт идемпотентен: повторный запуск обновляет код/данные и перезапускает процессы.
#
# Что делает:
#   1) клон/обновление репо raulwulff6769/framework-lab @otschet-current (тот же клон, где сайт);
#   2) stand/stand.env: API = локальный сервер сайта (http://127.0.0.1:3000), STAND_ID прежний
#      (stand-vps) — карточка стенда в кабинете не задваивается;
#   3) данные стенда (.stand/stand-state.json — счётчики моточасов/пробега, mappings.json —
#      конфиг датчиков Galileosky) восстанавливаются из вшитых ниже base64 — телеметрия в БД
#      (Neon) уже общая, поэтому история 30 дней переносится автоматически;
#   4) запуск stand/run.sh (супервизор шлюза и стенда) + @reboot в cron;
#   5) проверки: порты шлюза слушаются, стенд отчитался в API (HTTP 200).
#
# Очередь неотправленных пакетов (gateway-queue.sqlite3) НЕ переносится: пока песочница Zo ещё
# работает, её шлюз дольёт очередь в API сам (ключ валиден). После запуска на VPS стенд
# продолжает с текущего момента — разрыва в истории не будет, если сначала дать Zo-стенду
# выкачать очередь до нуля (status .stand/gateway-status.json → queue: 0).
set -euo pipefail

APP_DIR="${APP_DIR:-$HOME/itles}"
BRANCH="${BRANCH:-otschet-current}"
REPO="${REPO:-https://github.com/raulwulff6769/framework-lab.git}"
API_URL="${API_URL:-http://127.0.0.1:3000}"
STAND_ID="${STAND_ID:-stand-vps}"
HOST_LABEL="${HOST_LABEL:-VPS Singapore (Tencent)}"

say(){ printf '\n\033[1;36m== %s ==\033[0m\n' "$1"; }
[ -n "${STAND_KEY:-}" ] || { echo "!! задайте STAND_KEY (ключ шлюза itg_...) перед запуском"; exit 1; }
command -v python3 >/dev/null || { echo "!! нужен python3 (apt-get install -y python3)"; exit 1; }
python3 -c 'import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)' || { echo "!! нужен Python 3.10+"; exit 1; }

say "1) код стенда: $APP_DIR @ $BRANCH"
if [ -d "$APP_DIR/.git" ]; then
  git -C "$APP_DIR" fetch --depth 1 origin "$BRANCH"
  git -C "$APP_DIR" checkout -q -B "$BRANCH" "origin/$BRANCH"
else
  git clone --depth 1 -b "$BRANCH" "$REPO" "$APP_DIR"
fi
git -C "$APP_DIR" log --oneline -1

say "2) конфиг stand.env (API=$API_URL)"
ENV="$APP_DIR/stand/stand.env"
cat > "$ENV" <<EOF
ITLES_API_URL=$API_URL
STAND_KEY=$STAND_KEY
STAND_ID=$STAND_ID
STAND_HOST_LABEL="$HOST_LABEL"
STAND_HISTORY_DAYS=30
TRACCAR_HOST=demo.traccar.org
TRACCAR_PORT_TELTONIKA=5027
TRACCAR_WEB=https://demo.traccar.org
EOF
chmod 600 "$ENV"

say "3) состояние парка и конфиг датчиков (из песочницы Zo)"
DATA="$APP_DIR/.stand"
mkdir -p "$DATA" && chmod 700 "$DATA"
printf '%s' '' | base64 -d > "$DATA/stand-state.json"
printf '%s' '' | base64 -d > "$DATA/mappings.json"
python3 -c "import json;a=json.load(open('$DATA/stand-state.json'));print('state:',len(a['units']),'юнитов, saved_at',a['saved_at'])"
python3 -c "import json;m=json.load(open('$DATA/mappings.json'));print('mappings:',len(m),'IMEI')"

say "4) остановить прежний стенд (если был) и запустить"
pkill -f "$APP_DIR/stand/run.sh" 2>/dev/null || true
sleep 1
nohup "$APP_DIR/stand/run.sh" > "$APP_DIR/stand/nohup.log" 2>&1 &
sleep 4

say "5) @reboot в cron (переживает перезагрузку VPS)"
if command -v crontab >/dev/null; then
  (crontab -l 2>/dev/null | grep -v "stand/run.sh"; echo "@reboot $APP_DIR/stand/run.sh > $APP_DIR/stand/nohup.log 2>&1") | crontab -
  echo "cron ok"
else
  echo "!! crontab нет — добавьте @reboot вручную: $APP_DIR/stand/run.sh"
fi

say "6) проверки"
for p in 5034 5037 5039 5041 5090; do
  python3 -c "import socket,sys;s=socket.socket();s.settimeout(2);sys.exit(0 if s.connect_ex(('127.0.0.1',$p))==0 else 1)" \
    && echo "порт $p: слушается" || echo "!! порт $p: НЕ слушается"
done
sleep 8
if [ -f "$DATA/gateway-status.json" ]; then
  python3 -c "import json;s=json.load(open('$DATA/gateway-status.json'));print('шлюз: connections',s['connections'],'queue',s['queue'],'errors',s['errors'],'last_error',s['last_error'])"
fi
tail -n 5 "$DATA/stand.log" 2>/dev/null || true
echo
echo "Готово. Логи: $DATA/{stand,gateway}.log. Остановить: pkill -f '$APP_DIR/stand/run.sh'"
echo "Карточка стенда в кабинете: id=$STAND_ID (та же, что была с песочницы)."
